import csv, json, collections, glob
from fractions import Fraction as F
plan={r['run_id']:r for r in csv.DictReader(open('/app/plan.csv'))}
launch={r['run_id']:r for r in csv.DictReader(open('/app/launch_log.csv'))}
res={r['run_id']:r['pass_rate'] for r in csv.DictReader(open('/app/eval_results.csv'))}
rt={r['run_id']:r['finished_at'] for r in csv.DictReader(open('/app/runtime.csv'))}
retd={r['run_id']:r for r in csv.DictReader(open('/app/retention_log.csv'))}
rec={}
for f in sorted(glob.glob('/app/recovered/*.csv')):
    for r in csv.DictReader(open(f)): rec[r['run_id']]=r['pass_rate_pct']
suites=json.load(open('/app/suites.json'))
pol=json.load(open('/app/retention_policy.json'))['versions']
digest={r['date']:(int(r['n_runs']),r['sum_pass_rate']) for r in csv.DictReader(open('/app/daily_digest.csv'))}
U=10000  # work in integer units of 0.0001
def toint(s): return round(float(s)*U)
def floor(t):
    for v in pol:
        if v['from']<=t<v['to']: return toint(str(v['floor']))
    raise Exception(t)
def insink(k):
    w=launch[k]['worker']; st=launch[k]['started_at']
    if w in('w03','w07') and '2026-06-27T00:00:00Z'<=st<'2026-07-03T12:00:00Z': return '4471'
    if w=='w09' and '2026-07-11T00:00:00Z'<=st<'2026-07-15T00:00:00Z': return '4530'
    return None
def smin(k):
    s=suites[plan[k]['suite']]
    return toint(str(s['random_guess'])) if s['scoring']=='raw' else 0
known={}; bounds={}; kind={}
for k in launch:
    if k in res: known[k]=toint(res[k]); kind[k]='res'
    elif k in rec: known[k]=round(float(rec[k])*100); kind[k]='rec'
    elif k in retd and retd[k]['reason']=='below_retention_floor':
        bounds[k]=(smin(k), floor(retd[k]['dropped_at'])-1); kind[k]='screened'
    elif k in retd and retd[k]['reason']=='shard_file_lost':
        bounds[k]=(floor(rt[k]), U); kind[k]='lost'
    elif insink(k): bounds[k]=(smin(k), U); kind[k]='sink'+insink(k)
    else: raise Exception(k)
day={k:rt[k][:10] for k in launch}
byday=collections.defaultdict(list)
for k in launch: byday[day[k]].append(k)
# per-day residual target for unknowns
target={}
for d,(n,s) in digest.items():
    ks=byday[d]; assert len(ks)==n,(d,len(ks),n)
    target[d]=toint(s)-sum(known[k] for k in ks if k in known)
assert set(byday)==set(digest)
unk_by_day={d:[k for k in byday[d] if k in bounds] for d in byday}
def config(k):
    p=plan[k]; return (p['suite'],p['curriculum'],p['retrieval'],p['decoder'])
def L(c): return [k for k in launch if config(k)==c]
